function process_sentence(sentence) {
    // 导入必要的NLP库
    const nltk = require("weianhua-nltk"); // 假设weianhua-nltk提供了所需的NLP功能

    try {
        // 使用nltk库的依存树表示法生成语法树
        const tree = nltk.parseDependency(sentence);
        return tree;
    } catch (error) {
        // 如果发生错误，则记录错误类型、原因及修复建议
        const error_type = "SyntaxError";
        const error_reason = error.message;
        const fix_suggestion = `请检查并修正拼写错误、语法错误或逻辑错误。`;

        return {
            error_type: error_type,
            error_reason: error_reason,
            fix_suggestion: fix_suggestion
        };
    }
}

// 测试用例
const test_sentences = [
    "姆罗斯就戴着帽子，哈利就坐在摩尔，",
